window.appendOriginalGlyph = (container, id) => {
 const record=window.ORACLE_ORIGINALS[String(id)];if(!record)return;
 const isCuhk=[record.src,record.remoteSrc,record.pageUrl,record.filename].some(value=>/humanum|cuhk\.edu/i.test(value||''));
 const box=document.createElement('div');box.className='original-glyph';box.style.cssText='margin-top:12px';
 const button=document.createElement('button');button.type='button';button.className='btn secondary';button.textContent='显示原图';button.setAttribute('aria-expanded','false');
 button.onclick=()=>{
  const panel=document.createElement('div');panel.style.cssText='display:flex;flex-direction:column;align-items:flex-start;gap:8px;margin-top:8px';
  for(const source of isCuhk?[]:(record.sourceLinks||[])){const link=document.createElement('a');link.href=source.url;link.textContent=source.label+' ↗';link.target='_blank';link.rel='noopener';link.style.display='block';panel.append(link);}
  const note=document.createElement('p');note.textContent=record.note;note.className='muted';panel.append(note);
  if(record.src){const img=document.createElement('img');img.alt=record.label+'的未经处理原图';img.src=record.src;img.style.cssText='display:block;width:auto;height:auto;min-width:120px;max-width:min(100%,400px);max-height:500px;object-fit:contain;background:white;border:1px solid #ddd';img.onerror=()=>{img.remove();note.textContent='原图暂时无法加载，请查看该字的来源页面。'};panel.append(img);
   const originalUrl=record.fullSrc||record.remoteSrc||record.src;
   if(!isCuhk&&!/humanum\.arts\.cuhk\.edu\.hk\/Lexis\/lexi-mf\/oracle\.php(?:\?|$)/i.test(originalUrl)){const link=document.createElement('a');link.href=originalUrl;link.target='_blank';link.rel='noopener';link.textContent=record.fullSrc?'打开完整来源图片 ↗':'打开来源原图 ↗';panel.append(link);}
   const filename=document.createElement('small');filename.textContent='原图文件：'+record.filename;panel.append(filename);
  }
  const hide=document.createElement('button');hide.type='button';hide.className='btn secondary';hide.textContent='收起原图';hide.onclick=()=>{panel.replaceWith(button);button.setAttribute('aria-expanded','false')};panel.append(hide);button.setAttribute('aria-expanded','true');button.replaceWith(panel);
 };box.append(button);container.append(box);return box;
};
